package io.github.jasper.monitoring.api.management.model;
public final class ControlAttemptView { private final long attempt; private final String status; public ControlAttemptView(long attempt,String status){if(attempt<1||status==null||(!"PENDING".equals(status)&&!"SUCCEEDED".equals(status)&&!"FAILED".equals(status)&&!"SKIPPED".equals(status)))throw new IllegalArgumentException("invalid attempt");this.attempt=attempt;this.status=status;} public long getAttempt(){return attempt;} public String getStatus(){return status;} }
